// The PDF is the complete submission; standalone photos do not start completion.
const f=$input.first().json,name=String(f.name||'');
if(!/\.pdf$/i.test(name))return [];
const m=name.match(/^TICKET[-_ ]?(\d+)(?:_after)?\.pdf$/i);
return [{json:{matched:!!m,ticket_id:m?Number(m[1]):null,upload_kind:'REPORT',report_file_id:f.id,report_file_name:name,report_link:f.webViewLink||''}}];

// Keep the extracted AFTER binary; a Drive download produces the BEFORE binary.
const report = $('Extract Report Text and Photo').first();
const item = $input.first();
const before = item.binary?.data;
const after = report.binary?.data;
const ready = !!before && !!after && !item.json.error;
return [{json:{...report.json, images_ready:ready},
  binary:ready ? {before_photo:before, data:after} : {}}];

const raw=String($input.first().json.text||'').trim().replace(/^```(json)?/i,'').replace(/```$/,'').trim();
let v;try{v=JSON.parse(raw);}catch{v={observations:'Image comparison returned no readable verdict.'};}
return [{json:{repair_verified:typeof v.repair_verified==='boolean'?v.repair_verified:null,ai_confidence:typeof v.confidence==='number'?Math.max(0,Math.min(1,v.confidence)):0,observations:v.observations||'No usable visual observation.'}}];

// One submission PDF contains the report text and its optional AFTER photo.
const x = $('Extract Ticket ID').first().json;
let text = '', pages = 0, parseError = null;
let photoStatus = 'UNKNOWN', photoError = null, photo = null, binary = {};
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (buf.length > 20 * 1024 * 1024) throw new Error('Report exceeds 20 MiB');
  const base = String($env.IFC_SERVICE_URL || '').replace(/\/+$/, '');
  if (!base) throw new Error('Configure IFC_SERVICE_URL');
  const parsed = await this.helpers.httpRequest({
    method: 'POST', url: base + '/reports/extract', json: true,
    body: {pdfB64: buf.toString('base64')}, timeout: 60000,
  });
  if (typeof parsed.text !== 'string' || !Number.isInteger(parsed.numpages)) {
    throw new Error('Invalid report extraction response');
  }
  text = parsed.text.replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  pages = parsed.numpages;
  photoStatus = ['OK','NONE','AMBIGUOUS','ERROR'].includes(parsed.photo_status) ? parsed.photo_status : 'ERROR';
  photoError = parsed.photo_error || (parsed.photo_status ? null : 'Python service does not support report photo extraction');
  if (photoStatus === 'OK') {
    try {
      photo = parsed.photo;
      if (!photo || photo.mime_type !== 'image/jpeg' || typeof photo.base64 !== 'string' || !photo.base64) throw new Error('Invalid extracted photo');
      const bytes = Buffer.from(photo.base64, 'base64');
      if (bytes.length > 10 * 1024 * 1024 || bytes[0] !== 255 || bytes[1] !== 216) throw new Error('Invalid extracted JPEG');
      binary.data = await this.helpers.prepareBinaryData(bytes, 'TICKET-' + x.ticket_id + '-after.jpg', 'image/jpeg');
    } catch (e) {
      photoStatus = 'ERROR'; photoError = String(e.message || e); photo = null;
    }
  }
} catch (e) {
  parseError = String(e?.response?.body?.detail || e?.message || e).slice(0, 1000);
}
const words = text ? text.split(/\s+/).filter(Boolean).length : 0;
const quality = parseError ? 'PARSE_ERROR' : (words < 5 ? 'EMPTY' : 'OK');
return [{json:{...x, report_text:text, report_words:words, report_pages:pages,
  report_quality:quality, report_parse_error:parseError,
  photo_available:photoStatus === 'OK', photo_status:photoStatus, photo_error:photoError,
  photo_source:photo?.source || null, photo_page:photo?.page || null,
  after_file_id:null, after_link:photoStatus === 'OK' ? (x.report_link || '') : ''}, binary}];

const report = $('Extract Report Text and Photo').first().json;
const ticket = $('Fetch Ticket').first().json;
let vision = null;
try {
  const v = $('Parse Verification').first().json;
  vision = {repair_verified:v.repair_verified, confidence:v.ai_confidence, observations:v.observations};
} catch {}
let summary;
if (vision) summary = `An AFTER photo was extracted from the PDF. Comparison verdict: repair_verified=${vision.repair_verified}, confidence=${vision.confidence}. ${vision.observations}`;
else if (report.photo_status === 'NONE') summary = 'No photograph was supplied. Judge the written report alone.';
else if (report.photo_status !== 'OK') summary = 'Photo extraction could not establish usable evidence (' + report.photo_status + '): ' + (report.photo_error || report.report_parse_error || 'unknown') + '. Do not claim the photo was absent or verified.';
else if (!ticket.before_file_id) summary = 'The PDF contains an AFTER photo, but the ticket has no BEFORE photo reference. No visual comparison was performed.';
else summary = 'The PDF contains an AFTER photo, but image comparison could not be completed. Do not treat the repair as visually verified.';
return [{json:{
  ticket_id:ticket.id, object_type:ticket.object_type || ticket.ifc_name || 'unspecified object',
  damage_description:ticket.damage_description || ticket.description || '',
  technician_name:ticket.technician_name || '', technician_email:ticket.technician_email || '',
  report_text:report.report_text, report_quality:report.report_quality, report_words:report.report_words,
  report_file_id:report.report_file_id, report_link:report.report_link,
  photo_supplied:report.photo_status === 'NONE' ? false : report.photo_status === 'OK' ? true : null,
  photo_status:report.photo_status, photo_source:report.photo_source, photo_page:report.photo_page,
  photo_error:report.photo_error, after_file_id:null, after_link:report.after_link || '',
  vision, vision_summary:summary
}}];

parameters.text:
=You are the completion-assessment engine of a facility-maintenance system. Decide whether a technician's written report credibly shows the work is finished.

TICKET {{ $json.ticket_id }} - object: {{ $json.object_type }}
Originally reported issue: {{ $json.damage_description }}
Technician: {{ $json.technician_name }}

TECHNICIAN'S REPORT (extraction quality: {{ $json.report_quality }}, {{ $json.report_words }} words):
---
{{ $json.report_text }}
---

PHOTOGRAPHIC EVIDENCE: {{ $json.vision_summary }}

The photograph is optional; the report is the evidence of record. Judge the report on whether it describes what was actually done to resolve the reported issue. A report that is empty, unreadable, generic, or describes work unrelated to the reported issue is not a completion.

Respond with ONLY a minified JSON object, no markdown fences:
{"work_complete": true or false, "confidence": number between 0 and 1, "recommended_status": one of "PENDING_APPROVAL" or "REWORK" or "NEEDS_TRIAGE", "summary": one short factual sentence for the facility manager, "concerns": short string, empty if none}

Use PENDING_APPROVAL when the report credibly describes the completed repair. Use REWORK when the work appears incomplete, unrelated, or the report is unusable. Use NEEDS_TRIAGE only when the report indicates the original diagnosis was wrong.

