SELECT result.*, (result.settled IS TRUE) AS verified
 FROM jsonb_to_record(cbm_wf2_closure_outcome($1::jsonb)) AS result
 (id int,status text,approval_id uuid,closed_at timestamptz,ifc_new_version text,settled boolean,missing_operations jsonb);

WITH audit AS (INSERT INTO ticket_events(ticket_id,event,payload)
 VALUES($1,'CBM_WF2_INCOMPLETE',$2::jsonb) RETURNING id)
 SELECT $2::jsonb->>'status' AS status,$2::jsonb->'missing_operations' AS missing_operations FROM audit;
